export class BatchIngestor {
  #maxBatchSize;
  #sinkFn;
  #buffer;
  #committedWatermarkSeq;
  #totalCommitted;

  /**
   * @param {{ maxBatchSize?: number, sinkFn: (batch: Array<object>) => Promise<void> }} options
   */
  constructor(options = {}) {
    if (typeof options.sinkFn !== 'function') {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'sinkFn must be a function');
    }
    const maxBatchSize = options.maxBatchSize ?? 50;
    if (!Number.isInteger(maxBatchSize) || maxBatchSize < 1) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'maxBatchSize must be positive integer');
    }
    this.#maxBatchSize = maxBatchSize;
    this.#sinkFn = options.sinkFn;
    this.#buffer = [];
    this.#committedWatermarkSeq = 0;
    this.#totalCommitted = 0;
  }

  /**
   * Buffers one event and triggers a flush if `maxBatchSize` is reached.
   *
   * @param {{ seq: number, metric: string, units: number }} event
   */
  async ingest(event) {
    if (!event || !Number.isInteger(event.seq) || typeof event.metric !== 'string') {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_EVENT, 'Event must have integer seq and string metric');
    }
    this.#buffer.push({ ...event });
    if (this.#buffer.length >= this.#maxBatchSize) {
      await this.flush();
    }
  }

  /**
   * Flushes all buffered events through `sinkFn`.
   */
  async flush() {
    if (this.#buffer.length === 0) return { flushedCount: 0 };
    const batch = this.#buffer.splice(0, this.#buffer.length);
    await this.#sinkFn(batch);
    for (const item of batch) {
      if (item.seq > this.#committedWatermarkSeq) {
        this.#committedWatermarkSeq = item.seq;
      }
    }
    this.#totalCommitted += batch.length;
    return { flushedCount: batch.length };
  }

  get pendingCount() {
    return this.#buffer.length;
  }

  get committedWatermarkSeq() {
    return this.#committedWatermarkSeq;
  }

  get totalCommitted() {
    return this.#totalCommitted;
  }
}
export const ERROR_CODES = Object.freeze({
  ERR_NEGATIVE_UNITS: 'ERR_NEGATIVE_UNITS',
  ERR_INVALID_TIERS: 'ERR_INVALID_TIERS',
  ERR_INVALID_AMOUNT: 'ERR_INVALID_AMOUNT',
  ERR_IDEMPOTENCY_CONFLICT: 'ERR_IDEMPOTENCY_CONFLICT',
  ERR_INVALID_TTL: 'ERR_INVALID_TTL',
  ERR_INVALID_CONFIG: 'ERR_INVALID_CONFIG',
  ERR_DSL_SYNTAX: 'ERR_DSL_SYNTAX',
  ERR_INVALID_TIMEZONE: 'ERR_INVALID_TIMEZONE',
  ERR_SINK_FAILURE: 'ERR_SINK_FAILURE',
  ERR_INVALID_EVENT: 'ERR_INVALID_EVENT'
});

export class LedgerError extends Error {
  /**
   * @param {string} code
   * @param {string} message
   * @param {object} [details]
   */
  constructor(code, message, details = undefined) {
    super(message);
    this.name = 'LedgerError';
    this.code = code;
    if (details !== undefined) {
      this.details = details;
    }
  }
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { compileFilter } from '../src/queryDsl.mjs';
import { BatchIngestor } from '../src/batchIngestor.mjs';

test('T08 visible: escaped trailing backslash and AND-over-OR precedence', () => {
  const pathPred = compileFilter('path == "C:\\\\temp\\\\"');
  assert.equal(pathPred({ path: 'C:\\temp\\' }), true);
  assert.equal(pathPred({ path: 'C:\\other\\' }), false);

  // AND binds tighter than OR: a == 1 OR (b == 2 AND c == 3)
  const precPred = compileFilter('a == 1 OR b == 2 AND c == 3');
  assert.equal(precPred({ a: 1, b: 0, c: 0 }), true);
  assert.equal(precPred({ a: 0, b: 2, c: 0 }), false);
});

test('T08 visible: BatchIngestor preserves events when sink rejects', async () => {
  let failOnce = true;
  const delivered = [];
  const ingestor = new BatchIngestor({
    maxBatchSize: 10,
    sinkFn: async (batch) => {
      if (failOnce) {
        failOnce = false;
        throw new Error('transient sink error');
      }
      delivered.push(...batch);
    }
  });
  await ingestor.ingest({ seq: 1, metric: 'm', units: 5 });
  await ingestor.ingest({ seq: 2, metric: 'm', units: 6 });

  await assert.rejects(() => ingestor.flush(), /transient sink error/);
  assert.equal(ingestor.pendingCount, 2);
  assert.equal(ingestor.committedWatermarkSeq, 0);

  await ingestor.flush();
  assert.equal(ingestor.pendingCount, 0);
  assert.equal(ingestor.committedWatermarkSeq, 2);
  assert.deepEqual(delivered.map((x) => x.seq), [1, 2]);
});
