function resolveField(obj, pathStr) {
  const parts = String(pathStr).split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, part)) return undefined;
    cur = cur[part];
  }
  return cur;
}

function isNullish(v) {
  return v === null || v === undefined;
}

function isUnorderable(v) {
  return isNullish(v) || (typeof v === 'number' && Number.isNaN(v));
}

function looseEquals(actual, target) {
  const an = isNullish(actual);
  const tn = isNullish(target);
  if (an || tn) return an && tn;
  return actual === target;
}

function compare(actual, op, target) {
  switch (op) {
    case '==': return looseEquals(actual, target);
    case '!=': return !looseEquals(actual, target);
    case '>':
    case '>=':
    case '<':
    case '<=':
      if (isUnorderable(actual) || isUnorderable(target)) return false;
      if (op === '>') return actual > target;
      if (op === '>=') return actual >= target;
      if (op === '<') return actual < target;
      return actual <= target;
    default: return false;
  }
}

/**
 * Compiles a filter expression string into `(event) => boolean`.
 *
 * Precedence (tightest first): `()` > `NOT` > `AND` > `OR`.
 *
 * @param {string} expr
 * @returns {(event: object) => boolean}
